WITH kept_keys AS (SELECT product_id, order_id FROM order_items INTERSECT SELECT product_id, order_id FROM order_items WHERE product_id IS NULL), reconciled AS (SELECT s.* FROM order_items s INNER JOIN kept_keys k ON s.product_id = k.product_id AND s.order_id = k.order_id), enriched AS (SELECT src.order_id, src.product_id, p.category, p.brand FROM reconciled src LEFT JOIN products p ON src.product_id = p.id), base AS (SELECT *, LENGTH(brand) AS brand_length, CASE WHEN brand IN ('Umbrella', 'Globex') THEN 'Priority' ELSE 'Other' END AS brand_group FROM enriched WHERE order_id IN (28, 32)), scored AS (SELECT *, RANK() OVER w_part AS brand_length_rank, RANK() OVER (ORDER BY brand_length NULLS FIRST) AS brand_length_rank_2 FROM base WINDOW w_part AS (PARTITION BY order_id ORDER BY brand_length DESC)), cleaned AS (SELECT order_id, product_id, brand_length, brand_length_rank_2, TRIM(brand) AS clean_brand, COALESCE(brand, 'UNKNOWN') AS brand_clean FROM scored WHERE product_id IS NOT NULL), enriched_order_items AS (SELECT src.*, d.amount FROM cleaned src LEFT JOIN orders d ON src.order_id = d.id), enriched_order_items_2 AS (SELECT *, CUME_DIST() OVER (PARTITION BY order_id, product_id ORDER BY brand_length) AS brand_length_cume_dist FROM enriched_order_items) SELECT product_id, kpi, reading FROM (SELECT product_id, amount, brand_length_cume_dist FROM enriched_order_items_2) src UNPIVOT INCLUDE NULLS (reading FOR kpi IN (amount, brand_length_cume_dist)) unp;
